```python
from cyclopts import App

app = App(name="fileman")

@app.command
def upload(path: str):
    """Upload a file"""
    print(f"Would upload: {path}")

@app.command
def download(url: str, *, dest: str):
    """Download a file"""
    print(f"URL: {url}")
    print(f"Destination: {dest}")

if __name__ == "__main__":
    app()
